"use client";

import * as React from "react";
import { RadioGroup as RadioGroupPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";

// Generated by shadcn, restyled with the Lachmat tokens. In the Figma a radio is
// never a circle: each option is a gray box with its label, black when checked
// (e.g. the sizes on the product page). Radix handles the radio semantics: arrow
// keys move between options, and with `name` it submits like a native radio.
const RadioGroup = ({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Root>) => {
  return (
    <RadioGroupPrimitive.Root
      data-slot="radio-group"
      className={cn("flex flex-wrap gap-2", className)}
      {...props}
    />
  );
};

const RadioGroupItem = ({
  className,
  ...props
}: React.ComponentProps<typeof RadioGroupPrimitive.Item>) => {
  return (
    <RadioGroupPrimitive.Item
      data-slot="radio-group-item"
      className={cn(
        // flex-auto: the boxes share the row, each one wider for a longer label (PP, GGG)
        // hover uses brightness, not a bg-* color: data-checked: is a :where() selector (zero
        // specificity), so a hover:bg-* would beat data-checked:bg-ink and show white text on a light box
        "flex-auto bg-input px-3 py-3 type-body text-[18px] text-ink transition-colors outline-offset-2 hover:brightness-95 focus-visible:outline-2 focus-visible:outline-ink data-checked:bg-ink data-checked:text-white",
        // out of stock, for example
        "disabled:cursor-not-allowed disabled:text-ink/30 disabled:line-through disabled:hover:brightness-100",
        "aria-invalid:outline-1 aria-invalid:outline-offset-[-1px] aria-invalid:outline-discount",
        className,
      )}
      {...props}
    />
  );
};

export { RadioGroup, RadioGroupItem };
